function animateStatCount(id,target,formatter=value=>String(value)){const element=$(`#${id}`),previous=statTargets.get(id);if(!element||previous===target)return;statTargets.set(id,target);const oldFrame=statFrames.get(id);if(oldFrame)cancelAnimationFrame(oldFrame);if(previous===undefined||window.matchMedia?.('(prefers-reduced-motion: reduce)').matches){element.textContent=formatter(target);element.dataset.statValue=String(target);return;}const from=Number(element.dataset.statValue??previous),duration=420;let startedAt;const tick=now=>{startedAt??=now;const progress=Math.min(1,(now-startedAt)/duration),eased=1-(1-progress)**3,value=Math.round(from+(target-from)*eased);element.textContent=formatter(value);element.dataset.statValue=String(value);if(progress<1)statFrames.set(id,requestAnimationFrame(tick));else{statFrames.delete(id);element.classList.remove('is-counting');}};element.classList.remove('is-counting');void element.offsetWidth;element.classList.add('is-counting');statFrames.set(id,requestAnimationFrame(tick));}
