async function companyLogoData(file){if(!file)return null;if(!['image/png','image/jpeg','image/webp'].includes(file.type))throw new Error('Choose a PNG, JPG, or WebP image.');if(file.size>10*1024*1024)throw new Error('Company logo files must be 10 MB or smaller.');let bitmap;try{bitmap=await createImageBitmap(file);}catch{throw new Error('This image could not be opened. Choose a PNG, JPG, or WebP image.');}try{if(bitmap.width<1||bitmap.height<1||bitmap.width>12000||bitmap.height>12000||bitmap.width*bitmap.height>50000000)throw new Error('This image has too many pixels. Choose a smaller logo.');const scale=Math.min(1,512/Math.max(bitmap.width,bitmap.height)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(bitmap.width*scale));canvas.height=Math.max(1,Math.round(bitmap.height*scale));const context=canvas.getContext('2d');if(!context)throw new Error('The image could not be prepared.');context.drawImage(bitmap,0,0,canvas.width,canvas.height);let blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/webp',.84));if(!blob||blob.type!=='image/webp')blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/png'));if(blob?.size>512*1024&&blob.type==='image/webp')blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/webp',.62));if(!blob||blob.size>512*1024)throw new Error('The logo is still too large after resizing. Choose a simpler image.');return await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result));reader.onerror=()=>reject(new Error('The image could not be read.'));reader.readAsDataURL(blob);});}finally{bitmap.close?.();}}
