const calendarColorNames={gold:'Gold',blue:'Blue',green:'Green',coral:'Coral',violet:'Violet',teal:'Teal',rose:'Rose',orange:'Orange'};
let currentUtilityKind=null,pendingProfileLeaveAfterSave=false,profilePromptReturnFocus=null,profileSaveInProgress=false;
function calendarColorOptionsMarkup(){return(state.user?.calendarColorOptions||Object.keys(calendarColorNames).map(color=>({color,available:true}))).map(option=>{const color=option.color,label=calendarColorNames[color]||color,isSelected=color===state.user?.calendarColor,isAvailable=option.available||isSelected;return`<label class="profile-calendar-color-choice"><input type="radio" name="calendarColor" value="${escapeHtml(color)}" ${isSelected?'checked':''} ${isAvailable?'':'disabled'}><span class="profile-calendar-color-chip ${isSelected?'is-selected':''}"><i class="calendar-color-swatch ${escapeHtml(color)}" aria-hidden="true"></i><strong>${escapeHtml(label)}</strong><small>${isSelected?'Your color':isAvailable?'Available':'In use'}</small></span></label>`;}).join('');}
function profileFormHasUnsavedChanges(){const form=$('#profileDetailsForm'),user=state.user;if(!form||!user)return false;const values=new FormData(form),value=name=>values.get(name)||'';return value('name')!==(user.name||'')||value('jobTitle')!==(user.jobTitle||'')||value('phone')!==(user.phone||'')||value('location')!==(user.location||'')||value('timeZone')!==(user.timeZone||browserTimeZone())||value('calendarColor')!==(user.calendarColor||'gold')||form.elements.directoryVisible.checked!==(user.directoryVisible!==false)||form.elements.shareEmail.checked!==!!user.shareEmail||form.elements.sharePhone.checked!==!!user.sharePhone||form.elements.shareLocation.checked!==!!user.shareLocation;}
function showProfileLeavePrompt(){profilePromptReturnFocus=document.activeElement;$('#profileUnsavedBackdrop').hidden=false;$('#profileStay').focus();}
function hideProfileLeavePrompt(){const focusTarget=profilePromptReturnFocus;profilePromptReturnFocus=null;$('#profileUnsavedBackdrop').hidden=true;if(focusTarget?.isConnected)focusTarget.focus();}
function accountSettingsMarkup(role){
 const memberships=state.user?.memberships?.filter(item=>item.active)||[],access=state.user?.role==='admin'?'All company workspaces':memberships.map(item=>item.name).join(', ')||'No active company access';
  return `<div class="account-summary"><div><span>Name</span><strong>${escapeHtml(state.user?.name)}</strong></div><div><span>Work email</span><strong>${escapeHtml(state.user?.email)}</strong></div><div><span>Role</span><strong>${escapeHtml(role)}</strong></div><div class="account-summary-wide"><span>Company access</span><strong>${escapeHtml(access)}</strong></div></div><form id="profileDetailsForm" class="profile-password-form"><h3>Your profile</h3><p>These details help coworkers know who you are. Your work email stays private unless you choose to share it in the directory.</p><div class="form-grid"><label class="form-field">Display name <span>*</span><input name="name" required minlength="2" maxlength="120" value="${escapeHtml(state.user?.name||'')}"></label><label class="form-field">Job title<input name="jobTitle" maxlength="120" value="${escapeHtml(state.user?.jobTitle||'')}" placeholder="e.g. Project manager"></label><label class="form-field">Phone<input name="phone" maxlength="40" value="${escapeHtml(state.user?.phone||'')}" placeholder="Work phone or extension"></label><label class="form-field">Location<input name="location" maxlength="120" value="${escapeHtml(state.user?.location||'')}" placeholder="City, state"></label><label class="form-field full-field">Calendar time zone<select name="timeZone" required>${timeZoneOptionsHtml(state.user?.timeZone||browserTimeZone())}</select><small>Used to display shared calendar events in your local time.</small></label><fieldset class="profile-calendar-color-fieldset full-field"><legend>Calendar color</legend><p>Choose the color used to identify your events. People who share a company calendar must have different colors.</p><div class="profile-calendar-color-options" id="profileCalendarColorOptions">${calendarColorOptionsMarkup()}</div></fieldset></div><fieldset class="profile-privacy-fieldset"><legend>People directory privacy</legend><label class="profile-privacy-option"><input type="checkbox" name="directoryVisible" ${state.user?.directoryVisible===false?'':'checked'}><span><strong>Show my profile in the directory</strong><small>People with access to one of your companies can find your profile.</small></span></label><label class="profile-privacy-option"><input type="checkbox" name="shareEmail" ${state.user?.shareEmail?'checked':''}><span><strong>Share my work email</strong><small>Otherwise it is visible only to you and platform administrators.</small></span></label><label class="profile-privacy-option"><input type="checkbox" name="sharePhone" ${state.user?.sharePhone?'checked':''}><span><strong>Share my phone number</strong><small>Phone numbers are private unless you turn this on.</small></span></label><label class="profile-privacy-option"><input type="checkbox" name="shareLocation" ${state.user?.shareLocation?'checked':''}><span><strong>Share my location</strong><small>Location is private unless you turn this on.</small></span></label></fieldset><div class="form-error" id="profileDetailsError" role="alert"></div><div class="form-success" id="profileDetailsSuccess" role="status"></div><div class="modal-actions"><button type="submit" class="button button-primary" id="saveProfileDetails">Save profile</button></div></form><section class="profile-password-form profile-sessions"><h3>Active sessions</h3><p>Review where your account is signed in. You can sign out all other sessions from here.</p><div id="activeSessionList" class="active-session-list" aria-live="polite">Loading sessions…</div><button type="button" class="button button-secondary" id="revokeOtherSessions">Sign out other sessions</button><div class="form-success" id="sessionActionMessage" role="status"></div></section><form id="profilePasswordForm" class="profile-password-form"><h3>Change your password</h3><label class="form-field">Current password<input name="currentPassword" type="password" required autocomplete="current-password"></label><label class="form-field">New password<input name="newPassword" type="password" required minlength="12" autocomplete="new-password"></label><label class="form-field">Confirm new password<input name="confirmPassword" type="password" required minlength="12" autocomplete="new-password"></label><div class="form-error" id="profilePasswordError" role="alert"></div><div class="form-success" id="profilePasswordSuccess" role="status"></div><div class="modal-actions"><button type="submit" class="button button-primary" id="saveOwnPassword">Update password</button></div></form>`;
}
const accountSessionDateTimeFormatter=new Intl.DateTimeFormat(),accountSessionDateFormatter=new Intl.DateTimeFormat(undefined,{dateStyle:'short'});
async function loadAccountSessions(list=$('#activeSessionList')){
 if(!list?.isConnected)return;list.textContent='Loading sessions…';
 try{const sessions=await api('/api/auth/sessions');if(!list.isConnected)return;list.innerHTML=sessions.length?sessions.map(session=>`<article class="active-session"><strong>${session.isCurrent?'This device':'Other signed-in session'}</strong><span>${escapeHtml(session.companyName)}</span><small>Signed in ${escapeHtml(accountSessionDateTimeFormatter.format(new Date(session.createdAt)))} · expires ${escapeHtml(accountSessionDateFormatter.format(new Date(session.expiresAt)))}</small></article>`).join(''):'<p class="people-empty">No active sessions found.</p>';const revoke=$('#revokeOtherSessions');if(revoke)revoke.disabled=!sessions.some(session=>!session.isCurrent);}catch(error){if(list.isConnected)list.textContent=error.message;}
}
function scheduleAccountSessions(){const list=$('#activeSessionList');if(!list)return;const load=()=>{if(list.isConnected&&!$('#utilityBackdrop').hidden)loadAccountSessions(list);};if(window.requestIdleCallback)window.requestIdleCallback(load,{timeout:1000});else window.setTimeout(load,120);}
function openUtility(kind){
 if(kind==='activity'){window.switchView('activity');return;}
 currentUtilityKind=kind;
  const role=state.user?.role==='admin'?'Platform administrator':'Company member';
 const views={
  help:{eyebrow:'WORKSPACE GUIDE',title:'Help center',body:`<div class="utility-copy"><h3>Choose a company workspace</h3><p>Open a company from the sidebar or Companies page. Its workspace keeps that company’s Reception Intake, tasks, notes, documents, and shared work together.</p><h3>Coordinate work</h3><p>Use Reception Intake to record inquiries and track who will follow up. Use Current work tasks to coordinate company work and calendar events. Use Projects for ongoing teamwork.</p><h3>Access and passwords</h3><p>Your role determines what you can change. Contact a portal administrator if your company access is wrong or you need a password reset.</p>${state.user?.role==='admin'?'<button type="button" class="button button-secondary" data-utility-action="access">Manage access</button>':''}</div>`},
  privacy:{eyebrow:'DATA HANDLING',title:'Data & privacy',body:'<div class="utility-copy"><h3>Company-scoped access</h3><p>The portal checks company access before showing records and files. Platform administrators can manage all companies; members are limited to their assigned company portals.</p><h3>Where information is stored</h3><p>Company profiles, reception inquiries, tasks, notes, and uploaded files are stored on the server hosting this portal. Files are delivered through authenticated routes rather than the public website folder.</p><h3>Backups</h3><p>Portal backups include company information, reception inquiries, uploaded files, and password hashes. Administrators can manage snapshots from Backups. Keep backup copies protected and limit access to the server.</p><p class="utility-note">This page describes how this portal is configured; it is not an organization-wide privacy policy.</p></div>'},
  profile:{eyebrow:'YOUR ACCOUNT',title:'Account settings',body:''}
 };
  const content=views[kind];if(!content)return;if(kind==='profile')content.body=accountSettingsMarkup(role);
  $('#utilityEyebrow').textContent=content.eyebrow;$('#utilityTitle').textContent=content.title;$('#utilityBody').innerHTML=content.body;if(kind==='profile')enhanceSearchableSelects($('#utilityBody'));$('#utilityBackdrop').hidden=false;$('#utilityClose').focus();if(kind==='profile')scheduleAccountSessions();
}
function closeUtility(force=false){if(!force&&currentUtilityKind==='profile'){if(profileSaveInProgress){showToast('Your profile is still saving. Please wait.');return false;}if(profileFormHasUnsavedChanges()){showProfileLeavePrompt();return false;}}$('#utilityBackdrop').hidden=true;$('#utilityBody').innerHTML='';currentUtilityKind=null;return true;}
window.openAccountSettings=()=>openUtility('profile');
$('#utilityBody').addEventListener('change',event=>{const selected=event.target.closest('input[name="calendarColor"]');if(!selected)return;$('#profileCalendarColorOptions')?.querySelectorAll('.profile-calendar-color-choice').forEach(choice=>{const radio=choice.querySelector('input[name="calendarColor"]'),chip=choice.querySelector('.profile-calendar-color-chip'),status=chip?.querySelector('small');if(!radio||!chip||!status)return;chip.classList.toggle('is-selected',radio.checked);status.textContent=radio.checked?(radio.value===state.user?.calendarColor?'Your color':'Selected'):radio.disabled?'In use':'Available';});});
$('#profileStay').addEventListener('click',hideProfileLeavePrompt);
$('#profileDiscard').addEventListener('click',()=>{profilePromptReturnFocus=null;$('#profileUnsavedBackdrop').hidden=true;closeUtility(true);});
$('#profileSaveAndLeave').addEventListener('click',()=>{const form=$('#profileDetailsForm');profilePromptReturnFocus=null;$('#profileUnsavedBackdrop').hidden=true;if(!form?.reportValidity())return;pendingProfileLeaveAfterSave=true;form.requestSubmit();});
$('#profileUnsavedBackdrop').addEventListener('keydown',event=>{if(event.key!=='Tab')return;const buttons=[...$('#profileUnsavedBackdrop').querySelectorAll('button:not(:disabled)')],first=buttons[0],last=buttons[buttons.length-1];if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus();}});
document.addEventListener('keydown',event=>{if(event.key==='Escape'&&!$('#profileUnsavedBackdrop').hidden){event.preventDefault();event.stopImmediatePropagation();hideProfileLeavePrompt();}},true);
window.addEventListener('beforeunload',event=>{if(currentUtilityKind==='profile'&&profileFormHasUnsavedChanges()){event.preventDefault();event.returnValue='';}});
$('#utilityBody').addEventListener('submit',async event=>{
  if(event.target.id!=='profileDetailsForm')return;event.preventDefault();const form=event.target,button=$('#saveProfileDetails'),values=Object.fromEntries(new FormData(form).entries()),colorChanged=values.calendarColor!==state.user?.calendarColor,leaveAfterSave=pendingProfileLeaveAfterSave,payload={...values,directoryVisible:form.elements.directoryVisible.checked,shareEmail:form.elements.shareEmail.checked,sharePhone:form.elements.sharePhone.checked,shareLocation:form.elements.shareLocation.checked};setError('#profileDetailsError','');$('#profileDetailsSuccess').textContent='';profileSaveInProgress=true;button.disabled=true;button.textContent='Saving…';
  try{const result=await api('/api/auth/profile',{method:'PATCH',body:JSON.stringify(payload)});pendingProfileLeaveAfterSave=false;state.user=result.user;updateProfile();if(leaveAfterSave)closeUtility(true);else{openUtility('profile');$('#profileDetailsSuccess').textContent='Your profile and calendar color were saved.';}if(colorChanged)window.refreshCalendar?.();if(state.view==='people')await window.loadPeople?.();showToast('Profile updated.');}catch(error){pendingProfileLeaveAfterSave=false;if(error.status===409){try{const fresh=await api('/api/auth/me');state.user=fresh.user;const choices=$('#profileCalendarColorOptions');if(choices)choices.innerHTML=calendarColorOptionsMarkup();}catch{}}setError('#profileDetailsError',error.message);}finally{profileSaveInProgress=false;if(button.isConnected){button.disabled=false;button.textContent='Save profile';}}
});
$('#utilityBody').addEventListener('click',async event=>{if(event.target.id!=='revokeOtherSessions')return;if(!confirm('Sign out all your other active sessions? This device will stay signed in.'))return;const button=event.target;button.disabled=true;$('#sessionActionMessage').textContent='';try{const result=await api('/api/auth/sessions/revoke-others',{method:'POST',body:'{}'});$('#sessionActionMessage').textContent=result.revoked?`${result.revoked} other session${result.revoked===1?'':'s'} signed out.`:'There were no other sessions to sign out.';await loadAccountSessions();}catch(error){$('#sessionActionMessage').textContent=error.message;button.disabled=false;}});
function searchCategoryForKind(kind){return searchCategoryConfig.find(category=>category.kinds.includes(kind))?.id||'other';}
function searchKindLabel(kind){return({company:'Company',task:'Task',calendar:'Calendar event',intake:'Reception inquiry',document:'Document',note:'Company note',person:'Person'})[kind]||'Record';}
function buildSearchParams({query=searchUi.query,page=searchUi.page,sort=searchUi.sort,categories=searchUi.categories}={}){
 const params=new URLSearchParams({q:query,page:String(page),sort});
 if(categories.length&&categories.length<searchCategoryConfig.length){params.set('types',categories.flatMap(id=>searchCategoryConfig.find(item=>item.id===id)?.kinds||[]).join(','));}
 const company=$('#advancedCompanyFilter')?.value||'',status=$('#advancedStatusFilter')?.value||'',owner=$('#advancedOwnerFilter')?.value||'',updated=document.querySelector('[name="advancedUpdated"]:checked')?.value||'';
 if(company)params.set('company',company);if(status)params.set('status',status);if(owner)params.set('owner',owner);if(updated)params.set('updated',updated);
 return params;
}
function escapeRegExp(value){return value.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');}
function highlightSearchText(value,query){
 const source=String(value||''),terms=[...new Set(String(query||'').trim().split(/\s+/).filter(Boolean))].sort((a,b)=>b.length-a.length);if(!terms.length)return escapeHtml(source);
 const matcher=new RegExp(terms.map(escapeRegExp).join('|'),'ig');let result='',last=0,match;
 while((match=matcher.exec(source))){result+=escapeHtml(source.slice(last,match.index))+`<mark>${escapeHtml(match[0])}</mark>`;last=match.index+match[0].length;if(!match[0].length)matcher.lastIndex++;}
 return result+escapeHtml(source.slice(last));
}
function quickSearchResultMarkup(item,index){const selected=index===searchUi.quickIndex;return`<button type="button" class="global-search-result ${selected?'is-active':''}" role="option" aria-selected="${selected}" data-search-kind="${escapeHtml(item.kind)}" data-search-id="${escapeHtml(item.id)}"><span class="search-result-type">${escapeHtml(searchKindLabel(item.kind).toUpperCase())}</span><span class="search-result-copy"><strong>${escapeHtml(item.title)}</strong><small>${escapeHtml([item.companyName,item.status,item.owner].filter(Boolean).join(' · ')||item.summary)}</small></span><span class="search-result-arrow" aria-hidden="true">↗</span></button>`;}
function renderGlobalSearchResults(message=''){
 const query=$('#globalSearchInput').value.trim(),results=$('#globalSearchResults');
 if(message){results.innerHTML=`<p class="search-hint ${message.startsWith('Search failed')?'search-error':''}">${escapeHtml(message)}</p>`;return;}
 if(!query){results.innerHTML='<p class="search-hint">Search companies, tasks, inquiries, calendar events, documents, notes, and people in your accessible workspaces.</p>';return;}
 const matches=searchUi.quickResponse?.results||[];
 if(!searchUi.quickResponse){results.innerHTML='<p class="search-hint">Searching your accessible workspace records…</p>';return;}
 results.innerHTML=matches.length?matches.slice(0,8).map(quickSearchResultMarkup).join(''):`<p class="search-hint">No matching records found. Try a shorter phrase or use Advanced Search.</p>`;
 $('#globalSearchInput').setAttribute('aria-activedescendant',searchUi.quickIndex>=0?`quick-search-result-${searchUi.quickIndex}`:'');
 results.querySelectorAll('[role="option"]').forEach((item,index)=>item.id=`quick-search-result-${index}`);
}
async function fetchQuickSearch(query){const sequence=++searchUi.quickSequence;searchUi.quickResponse=null;searchUi.quickIndex=-1;renderGlobalSearchResults();try{const params=new URLSearchParams({q:query,page:'1',sort:'relevance'}),response=await api('/api/search?'+params);if(sequence!==searchUi.quickSequence||$('#globalSearchInput').value.trim()!==query)return;searchUi.quickResponse=response;renderGlobalSearchResults();}catch(error){if(sequence===searchUi.quickSequence)renderGlobalSearchResults(`Search failed: ${error.message}`);}}
function openGlobalSearch(){if(!state.user)return;searchUi.quickResponse=null;searchUi.quickIndex=-1;$('#searchBackdrop').hidden=false;$('#globalSearchInput').value='';$('#globalSearchInput').removeAttribute('aria-activedescendant');renderGlobalSearchResults();$('#globalSearchInput').focus();}
function closeGlobalSearch(){$('#searchBackdrop').hidden=true;$('#globalSearchInput').value='';searchUi.quickResponse=null;searchUi.quickIndex=-1;$('#globalSearchInput').removeAttribute('aria-activedescendant');$('#globalSearchResults').innerHTML='<p class="search-hint">Search the companies and workspaces you can access.</p>';}
function renderAdvancedCategories(response=searchUi.response){
 const host=$('#advancedSearchCategories');if(!host)return;const counts=response?.counts||{},all=searchCategoryConfig.reduce((sum,item)=>sum+(counts[item.id]||0),0);
 const allSelected=!searchUi.categories.length;host.innerHTML=`<button type="button" class="advanced-category ${allSelected?'is-selected':''}" data-search-category="all" aria-pressed="${allSelected}"><span>All</span><b>${all}</b></button>`+searchCategoryConfig.map(category=>{const selected=searchUi.categories.includes(category.id),count=counts[category.id]||0;return`<button type="button" class="advanced-category ${selected?'is-selected':''}" data-search-category="${category.id}" aria-pressed="${selected}"><span>${escapeHtml(category.label)}</span><b>${count}</b></button>`;}).join('');
}
function renderAdvancedFilters(response=searchUi.response){
 const typeHost=$('#advancedTypeFilters');if(!typeHost)return;const counts=response?.counts||{};
 typeHost.innerHTML=searchCategoryConfig.map(category=>`<label class="advanced-type-option"><input type="checkbox" value="${category.id}" data-search-type ${!searchUi.categories.length||searchUi.categories.includes(category.id)?'checked':''}><span>${escapeHtml(category.label)}</span><b>${counts[category.id]||0}</b></label>`).join('');
 const fill=(selector,values,label,current)=>{const select=$(selector);if(!select)return;select.innerHTML=`<option value="">${label}</option>`+values.map(value=>{const id=typeof value==='string'?value:value.id,text=typeof value==='string'?value:value.name;return`<option value="${escapeHtml(id)}">${escapeHtml(text)}</option>`;}).join('');select.value=current||'';};
 fill('#advancedCompanyFilter',response?.companies||[],'All companies',$('#advancedCompanyFilter').value);
 fill('#advancedStatusFilter',response?.statuses||[],'Any status',$('#advancedStatusFilter').value);
 fill('#advancedOwnerFilter',response?.owners||[],'Anyone',$('#advancedOwnerFilter').value);
}
function dateSearchLabel(value){if(!value)return'—';const date=new Date(value);return Number.isNaN(date.getTime())?'—':date.toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric'});}
function advancedResultCard(item){return`<button type="button" class="advanced-result-card" data-advanced-result data-result-kind="${escapeHtml(item.kind)}" data-result-id="${escapeHtml(item.id)}"><span class="advanced-result-icon icon-${escapeHtml(searchCategoryForKind(item.kind))}" aria-hidden="true">${searchIconMarkup(item.kind)}</span><span class="advanced-result-card-main"><span class="search-result-type">${escapeHtml(searchKindLabel(item.kind).toUpperCase())}</span><strong>${highlightSearchText(item.title,searchUi.query)}</strong><small>${escapeHtml(item.summary||item.companyName||'No additional details')}</small></span><span class="search-result-arrow" aria-hidden="true">↗</span><span class="advanced-result-card-meta">${escapeHtml(item.companyName||'')} · ${escapeHtml(item.status||'')} · ${escapeHtml(item.owner||'')}</span></button>`;}
function advancedResultRow(item){return`<tr class="advanced-result-row" data-advanced-result data-result-kind="${escapeHtml(item.kind)}" data-result-id="${escapeHtml(item.id)}" tabindex="0" role="link" aria-label="Open ${escapeHtml(searchKindLabel(item.kind))}: ${escapeHtml(item.title)}"><td><div class="advanced-result-name"><span class="advanced-result-icon icon-${escapeHtml(searchCategoryForKind(item.kind))}" aria-hidden="true">${searchIconMarkup(item.kind)}</span><span><strong>${highlightSearchText(item.title,searchUi.query)}</strong><small>${escapeHtml(item.summary||'No additional details')}</small></span></div></td><td><span class="advanced-result-type">${escapeHtml(searchKindLabel(item.kind))}</span></td><td>${escapeHtml(item.companyName||'—')}</td><td>${escapeHtml(item.owner||'—')}</td><td><span class="advanced-status">${escapeHtml(item.status||'—')}</span></td><td>${escapeHtml(dateSearchLabel(item.updatedAt))}</td><td><span class="advanced-result-arrow" aria-hidden="true">→</span></td></tr>`;}
function renderAdvancedResults(response=searchUi.response){
 const content=$('#advancedResultsContent'),summary=$('#advancedResultsSummary'),pageSummary=$('#advancedPageSummary'),pagination=$('#advancedPagination');if(!content)return;
 const total=response?.total||0,page=response?.page||1,pageSize=response?.pageSize||10,pages=Math.ceil(total/pageSize),results=response?.results||[];
 $('#advancedResultsTitle').textContent=total?`${total.toLocaleString()} ${total===1?'result':'results'}`:'Search results';
 summary.textContent=searchUi.query?`${total.toLocaleString()} ${total===1?'item':'items'} found across the records you can access.`:total?`${total.toLocaleString()} accessible records. Enter a keyword or narrow the filters.`:'Enter a keyword or choose filters to search your workspace.';
 if(!total){content.innerHTML=searchUi.query?'<div class="advanced-search-empty"><strong>No results found</strong><span>Try different words, clear a filter, or check another category.</span></div>':'<div class="advanced-search-empty"><strong>Search your workspace</strong><span>Search by name, details, phone, status, company, owner, or document name.</span></div>';pageSummary.textContent='';pagination.innerHTML='';return;}
 content.classList.toggle('is-grid',searchUi.layout==='grid');
 content.innerHTML=searchUi.layout==='grid'?`<div class="advanced-results-grid">${results.map(advancedResultCard).join('')}</div>`:`<div class="advanced-results-table-wrap"><table class="advanced-results-table"><thead><tr><th>Name</th><th>Type</th><th>Company</th><th>Owner</th><th>Status</th><th>Updated</th><th><span class="sr-only">Open</span></th></tr></thead><tbody>${results.map(advancedResultRow).join('')}</tbody></table></div>`;
 const start=(page-1)*pageSize+1,end=Math.min(page*pageSize,total);pageSummary.textContent=`Showing ${start}–${end} of ${total.toLocaleString()}`;
 const numbers=[...new Set([1,page-1,page,page+1,pages].filter(value=>value>=1&&value<=pages))].sort((a,b)=>a-b);let last=0;
 pagination.innerHTML=`<button type="button" class="advanced-page-button" data-search-page="${page-1}" ${page<=1?'disabled':''} aria-label="Previous page">‹</button>`+numbers.map(number=>{const dots=number>last+1?'<span class="advanced-page-dots">…</span>':'';last=number;return dots+`<button type="button" class="advanced-page-button ${number===page?'is-current':''}" data-search-page="${number}" aria-current="${number===page?'page':'false'}">${number}</button>`;}).join('')+`<button type="button" class="advanced-page-button" data-search-page="${page+1}" ${page>=pages?'disabled':''} aria-label="Next page">›</button>`;
}
async function runAdvancedSearch({page=1,query}={}){
 if(query!==undefined)searchUi.query=String(query).trim();else searchUi.query=$('#advancedSearchInput').value.trim();
 searchUi.page=page;searchUi.sort=$('#advancedSort').value;const sequence=++searchUi.sequence,params=buildSearchParams({page,query:searchUi.query,sort:searchUi.sort});
 $('#advancedResultsContent').innerHTML='<p class="advanced-search-empty">Searching accessible records…</p>';$('#advancedResultsSummary').textContent='';
 try{const response=await api('/api/search?'+params);if(sequence!==searchUi.sequence)return;searchUi.response=response;renderAdvancedFilters(response);renderAdvancedCategories(response);renderAdvancedResults(response);}catch(error){if(sequence!==searchUi.sequence)return;searchUi.response=null;$('#advancedResultsContent').innerHTML=`<p class="advanced-search-empty search-error">Search could not be completed: ${escapeHtml(error.message)}</p>`;$('#advancedResultsSummary').textContent='';$('#advancedPagination').innerHTML='';$('#advancedPageSummary').textContent='';}
}
function renderSavedSearches(){const select=$('#advancedSavedSearches');if(!select)return;let saved=[];try{saved=JSON.parse(localStorage.getItem(`aspect-searches-${state.user?.id||'guest'}`)||'[]');}catch{}select.innerHTML='<option value="">Saved searches</option>'+saved.map((item,index)=>`<option value="${index}">${escapeHtml(item.name)}</option>`).join('');}
