function notificationTime(value){const seconds=Math.max(0,Math.floor((Date.now()-new Date(value).getTime())/1000));if(seconds<60)return'Just now';if(seconds<3600)return`${Math.floor(seconds/60)} min ago`;if(seconds<86400)return`${Math.floor(seconds/3600)} hr ago`;if(seconds<604800)return`${Math.floor(seconds/86400)} days ago`;return new Date(value).toLocaleDateString(undefined,{month:'short',day:'numeric'});}
