function formatTaskDate(value){return value?new Date(value+'T12:00:00').toLocaleDateString('en-US',{year:'numeric',month:'short',day:'numeric'}):'No due date';}
function formatEventDate(event){if(event.allDay){const date=new Date(`${event.startDate||event.startsAt.slice(0,10)}T12:00:00Z`);return date.toLocaleDateString('en-US',{weekday:'short',month:'short',day:'numeric',year:'numeric',timeZone:'UTC'})+' · All day';}return formatAtTimeZone(event.startsAt,{weekday:'short',month:'short',day:'numeric',hour:'numeric',minute:'2-digit',timeZoneName:'short'});}
function eventIsPast(event){if(event.allDay){const now=new Date(),parts=new Intl.DateTimeFormat('en-CA',{timeZone:displayTimeZone(),year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(now),today=`${parts.find(part=>part.type==='year').value}-${parts.find(part=>part.type==='month').value}-${parts.find(part=>part.type==='day').value}`;return Boolean(event.endDateExclusive&&event.endDateExclusive<=today);}return Date.parse(event.endsAt)<Date.now();}
