 const query=state.taskSearch.trim().toLowerCase(),items=work.filter(item=>(!query||[item.title,item.description,item.companyName,item.assigneeName,item.location].some(value=>String(value||'').toLowerCase().includes(query)))&&(!state.taskCompanyFilter||item.companyId===state.taskCompanyFilter)&&(!state.taskStatusFilter||item.status===state.taskStatusFilter));
 items.sort((a,b)=>String(a.workType==='event'?a.startsAt:a.dueDate||a.updatedAt||'').localeCompare(String(b.workType==='event'?b.startsAt:b.dueDate||b.updatedAt||'')));
 if(!items.length){$('#taskList').innerHTML='<p class="task-empty">'+(work.length?'No tasks or events match these filters.':'No tasks or calendar events yet.')+'</p>';state.taskCompletionMotionId=null;return;}
