const navigationShell=document.querySelector('.app-shell'),navigationSidebar=$('#sidebar'),navigationMain=document.querySelector('.main-content'),navigationScrim=$('#sidebarScrim'),navigationButton=$('#mobileMenu'),navigationClose=$('#sidebarClose'),navigationBreakpoint=window.matchMedia('(max-width: 1024px)');
function setNavigationOpen(open){const mobile=navigationBreakpoint.matches;navigationSidebar.classList.toggle('open',mobile&&open);navigationSidebar.inert=mobile&&!open;navigationMain.inert=mobile&&open;navigationShell.classList.toggle('nav-collapsed',!mobile&&!open);navigationScrim.classList.toggle('visible',mobile&&open);navigationScrim.setAttribute('aria-hidden',String(!(mobile&&open)));const label=mobile?(open?'Close navigation':'Open navigation'):(open?'Collapse navigation':'Expand navigation');navigationButton.setAttribute('aria-expanded',String(open));navigationButton.setAttribute('aria-label',label);navigationButton.title=label;}
function isNavigationOpen(){return navigationBreakpoint.matches?navigationSidebar.classList.contains('open'):!navigationShell.classList.contains('nav-collapsed');}
function closeNavigation(restoreFocus=false){if(!navigationBreakpoint.matches)return;setNavigationOpen(false);if(restoreFocus)navigationButton.focus({preventScroll:true});}
window.closeNavigation=closeNavigation;
