async function loadBackups(){const backups=await api('/api/backups');state.backups=backups;$('#backupList').innerHTML=backups.length?backups.map(item=>`<article class="backup-row"><div class="backup-icon" aria-hidden="true">${iconMarkup('archive')}</div><div class="backup-info"><strong>${new Date(item.createdAt).toLocaleString('en-US',{dateStyle:'medium',timeStyle:'short'})}</strong><small>${item.documentCount} ${item.documentCount===1?'document':'documents'} · ${formatBackupBytes(item.totalBytes)}</small></div><div class="backup-actions"><button type="button" class="button button-secondary" data-backup-action="restore" data-backup-id="${escapeHtml(item.id)}">Restore</button><button type="button" class="backup-delete" data-backup-action="delete" data-backup-id="${escapeHtml(item.id)}" ${backups.length<=1?'disabled':''} aria-label="Delete backup">×</button></div></article>`).join(''):'<p class="document-empty">No backups yet. Create your first snapshot above.</p>'; }
