function descendantsOf(id){return state.companies.filter(candidate=>{let parent=candidate.parentId;const visited=new Set();while(parent&&!visited.has(parent)){if(parent===id)return true;visited.add(parent);parent=state.companies.find(c=>c.id===parent)?.parentId||null;}return false;});}
